// A generic factory function template
template<typename T, typename... Ts>
T create_with_parens(Ts&&... args) {
  return T(std::forward<Ts>(args)...);
}

template<typename T, typename... Ts>
T create_with_braces(Ts&&... args) {
  return T{std::forward<Ts>(args)...};
}

// Calling code demonstrates the different outcomes
auto v1 = create_with_parens<std::vector<int>>(10, 20); // Creates a vector with 10 elements, each with value 20
auto v2 = create_with_braces<std::vector<int>>(10, 20);  // Creates a vector with 2 elements: 10 and 20
